<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$p=['product_name'=>'','slug'=>'','brand'=>'','category'=>'','short_description'=>'','best_for'=>'','price_text'=>'','affiliate_url'=>'','merchant'=>'','button_text'=>'View product','status'=>'draft','featured'=>0];if($pdo&&$id){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch()?:$p;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['product_name','slug','brand','category','short_description','best_for','price_text','affiliate_url','merchant','button_text','status'] as $k)$p[$k]=trim($_POST[$k]??'');$p['featured']=isset($_POST['featured'])?1:0;if($p['product_name']===''||$p['slug']===''||!filter_var($p['affiliate_url'],FILTER_VALIDATE_URL))$error='Product name, slug, and a valid affiliate URL are required.';elseif(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$p['slug']))$error='Invalid slug.';else{try{if($id){$q=$pdo->prepare('UPDATE products SET product_name=?,slug=?,brand=?,category=?,short_description=?,best_for=?,price_text=?,affiliate_url=?,merchant=?,button_text=?,status=?,featured=? WHERE id=?');$q->execute([$p['product_name'],$p['slug'],$p['brand'],$p['category'],$p['short_description'],$p['best_for'],$p['price_text'],$p['affiliate_url'],$p['merchant'],$p['button_text'],$p['status'],$p['featured'],$id]);}else{$q=$pdo->prepare('INSERT INTO products(product_name,slug,brand,category,short_description,best_for,price_text,affiliate_url,merchant,button_text,status,featured) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$p['product_name'],$p['slug'],$p['brand'],$p['category'],$p['short_description'],$p['best_for'],$p['price_text'],$p['affiliate_url'],$p['merchant'],$p['button_text'],$p['status'],$p['featured']]);}header('Location: products.php');exit;}catch(PDOException $e){$error='Unable to save product; the slug may already exist.';}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Product</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1><?=e($id?'Edit Product':'New Product')?></h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><form method="post" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Product name<input name="product_name" value="<?=e($p['product_name'])?>" required></label></p><p><label>Slug<input name="slug" value="<?=e($p['slug'])?>" required></label></p><p><label>Brand<input name="brand" value="<?=e($p['brand']??'')?>"></label></p><p><label>Category<input name="category" value="<?=e($p['category']??'')?>"></label></p><p><label>Short description<textarea name="short_description"><?=e($p['short_description']??'')?></textarea></label></p><p><label>Best for<input name="best_for" value="<?=e($p['best_for']??'')?>"></label></p><p><label>Price text<input name="price_text" value="<?=e($p['price_text']??'')?>"></label></p><p><label>Affiliate URL<input type="url" name="affiliate_url" value="<?=e($p['affiliate_url']??'')?>" required></label></p><p><label>Merchant<input name="merchant" value="<?=e($p['merchant']??'')?>"></label></p><p><label>Button text<input name="button_text" value="<?=e($p['button_text']??'View product')?>"></label></p><p><label>Status<select name="status"><?php foreach(['draft','published'] as $s):?><option <?=$p['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label></p><label><input type="checkbox" name="featured" <?=$p['featured']?'checked':''?>> Featured</label><p><button>Save product</button> <a href="products.php">Cancel</a></p></form></main></body></html>
